import {sourceSensitivityAvailable} from './source-sensitivity.mjs?v=20261023-final-1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const risks={high:'Высокий',medium:'Средний',low:'Низкий'};
const features={prize:'приз',payment:'обязательная оплата',random:'случайный выбор'};
export function sourceSensitivityView(c,value=null,{report=false}={}){
 const check=sourceSensitivityAvailable(c),result=value?.result;
 const inner=`<p>По очереди исключаем один материал только из расчёта и повторяем анализ тем же движком. Это проверка зависимости вывода от загруженных текстов. Оригиналы и ручные решения сохраняются.</p>${!check.available?`<p>${esc(check.reason)}</p>`:value?.busy?'<p role="status">Сравниваем результаты…</p>':value?.error?`<p role="alert">${esc(value.error)}</p>`:!result?(report?'<p>Сравнение ещё не выполнено.</p>':'<button class="button secondary" type="button" data-action="source-sensitivity">Сравнить источники</button>'):`<p><strong>Сейчас: ${esc(risks[result.baselineRisk])}.</strong> Источников, без которых высокий приоритет исчезает: ${result.essentialSources}.</p><div class="sensitivity-rows">${result.rows.map(r=>`<article><h4>Материал ${r.sourceIndex+1}${!r.included?' · не включён в оценку':''}</h4><p>Без него: <strong>${r.withoutRisk===null?'нет данных для оценки':esc(risks[r.withoutRisk])}</strong>${r.withoutRisk===result.baselineRisk?' · приоритет не изменился':''}.</p>${r.essentialForHigh?'<p><strong>Высокий приоритет зависит от этого материала.</strong></p>':''}${r.raisedByExclusion?'<p class="sensitivity-warning"><strong>После исключения приоритет повышается.</strong> Это повод изучить противоречие. Повышение не подтверждает, что источник можно отбросить.</p>':''}${r.lostCore.length?`<p>Перестали подтверждаться по правилам: ${r.lostCore.map(k=>esc(features[k])).join(', ')}.</p>`:''}${r.evidence.slice(0,3).map(e=>`<blockquote>${esc(e.quote)}</blockquote><small>Точный фрагмент исходного материала · позиции ${e.start}–${e.end}</small>`).join('')}${!report?`<button type="button" class="text-button" data-action="focus-source" data-source="${esc(r.sourceId)}">Открыть материал ${r.sourceIndex+1} →</button>`:''}</article>`).join('')}</div><p><small>Неизменный результат не доказывает достоверность или независимость источников: одинаковое утверждение может повторяться. Это поведение детектора, а не вероятность мошенничества.</small></p>`}`;
 return report?`<section class="source-sensitivity"><h2>Вклад источников в автоматический вывод</h2>${inner}</section>`:`<details class="source-sensitivity" ${value?'open':''}><summary>Какой источник меняет вывод?</summary>${inner}</details>`;
}
